/** Same 3-step shape for every product — the mechanics (status tabs, the
 * onboarding-gate concept, the skill list) are identical across all 4;
 * only the copy and which row to point at change. See this file's own
 * header for why this is generated instead of 4 hand-written tours. */
function buildProductTour(spec: ProductTourSpec): TourDefinition {
  return {
    id: spec.id,
    label: spec.label,
    description: spec.description,
    steps: [
      {
        id: "status-tabs",
        route: spec.productPath,
        target: '[data-tour="product-status-tabs"]',
        title: `${spec.label}'s skills`,
        body: `Filter this worker's own skill list by what's already enabled — everything here belongs to ${spec.label} specifically.`,
        placement: "bottom",
      },
      {
        id: "onboarding-worker",
        route: spec.productPath,
        target: `[data-tour="worker-row-${spec.onboardingWorkerId}"]`,
        title: spec.onboardingWorkerName,
        body: `This is where ${spec.label} starts. Every other skill in it stays locked until this one actually runs for this client — not just switched on, actually completed.`,
        placement: "top",
      },
      {
        id: "skill-list",
        route: spec.productPath,
        target: '[data-tour="product-skill-list"]',
        title: "Enable the rest",
        body: `Once ${spec.onboardingWorkerName} has run, every other ${spec.label} skill enables normally from this same list.`,
        placement: "top",
      },
    ],
  };
}

export const TOURS: TourDefinition[] = [
  { id: "dashboard-basics", label: "Dashboard Basics", description: "Orient yourself — Queue, Live Executions, sidebar, and the Create button.", steps: DASHBOARD_BASICS },
  { id: "library", label: "The Library", description: "Install a worker, then enable and configure the skills inside it.", steps: LIBRARY_BASICS },
  { id: "engagement-detail", label: "Your Client's Page", description: "Pause, reports, and every skill running for this one client.", steps: ENGAGEMENT_DETAIL },
  // One entry for every worker, not one per worker: the menu stays the
  // same size as workers are added (a new worker only adds a spec above).
  // A step whose worker page isn't there for this workspace is skipped by
  // the provider's target timeout.
  {
    id: "workers",
    label: "Your Workers",
    description: "How each worker starts: its setup skill runs first, then the rest enable from the same list.",
    steps: PRODUCT_TOUR_SPECS.flatMap((spec) => buildProductTour(spec).steps.map((s) => ({ ...s, id: `${spec.id}__${s.id}` }))),
  },
  // Each product's own three steps, kept as hidden tours: a setup form
  // starts its product's tour right after saving (startTour("showtime"),
  // "cold-open", "whop-agent"). Not listed in the picker, which only
  // shows "Your Workers".
  ...PRODUCT_TOUR_SPECS.map((spec) => ({ ...buildProductTour(spec), hidden: true })),
  {
    id: "full-walkthrough",
    label: "Full Walkthrough",
    description: "Everything above, back to back — the whole app in one pass.",
    steps: [
      { source: "dashboard-basics", steps: DASHBOARD_BASICS },
      { source: "library", steps: LIBRARY_BASICS },
      { source: "engagement-detail", steps: ENGAGEMENT_DETAIL },
      ...PRODUCT_TOUR_SPECS.map((spec) => ({ source: spec.id, steps: buildProductTour(spec).steps })),
    ].flatMap(({ source, steps }) => steps.map((s) => ({ ...s, id: `${source}__${s.id}` }))),
  },
];

export function getTour(tourId: string): TourDefinition | undefined {
  return TOURS.find((t) => t.id === tourId);
}
